// Biblioteca de funciones matemáticas (ejercicios 1-14 del bloque Funciones).
function esCapicua($n){$s=(string)abs((int)$n);return $s===strrev($s);}
function esPrimo($n){if($n<2)return false;for($i=2;$i*$i<=$n;$i++)if($n%$i==0)return false;return true;}
function siguientePrimo($n){do{$n++;}while(!esPrimo($n));return $n;}
function potencia($base,$exp){return $base**$exp;}
function digitos($n){return strlen((string)abs((int)$n));}
function voltea($n){return (int)strrev((string)abs((int)$n))*($n<0?-1:1);}
function digitoN($n,$pos){$s=(string)abs((int)$n);return isset($s[$pos])?(int)$s[$pos]:-1;}
function posicionDeDigito($n,$d){$p=strpos((string)abs((int)$n),(string)$d);return $p===false?-1:$p;}
function quitaPorDetras($n,$cantidad){$s=(string)abs((int)$n);return (int)substr($s,0,max(0,strlen($s)-max(0,$cantidad)));}
function quitaPorDelante($n,$cantidad){return (int)substr((string)abs((int)$n),max(0,$cantidad));}
function pegaPorDetras($n,$d){return (int)((string)$n.(string)abs((int)$d));}
function pegaPorDelante($n,$d){return (int)((string)abs((int)$d).(string)abs((int)$n));}
function trozoDeNumero($n,$inicio,$fin){return (int)substr((string)abs((int)$n),$inicio,max(0,$fin-$inicio+1));}
function juntaNumeros($a,$b){return (int)((string)$a.(string)abs((int)$b));}
// Biblioteca de arrays de una dimensión (ejercicios 20-28).
function generaArrayInt($n,$min,$max){$a=[];for($i=0;$i<$n&&$i<1000;$i++)$a[]=random_int(min($min,$max),max($min,$max));return $a;}
function minimoArrayInt($a){return $a?min($a):null;}
function maximoArrayInt($a){return $a?max($a):null;}
function mediaArrayInt($a){return $a?array_sum($a)/count($a):null;}
function estaEnArrayInt($a,$n){return in_array($n,$a);}
function posicionEnArray($a,$n){$i=array_search($n,$a);return $i===false?-1:$i;}
function volteaArrayInt($a){return array_reverse($a);}
function rotaDerechaArrayInt($a,$n){if(!$a)return $a;$n=(($n%count($a))+count($a))%count($a);return array_merge(array_slice($a,-$n),array_slice($a,0,count($a)-$n));}
function rotaIzquierdaArrayInt($a,$n){if(!$a)return $a;$n=(($n%count($a))+count($a))%count($a);return array_merge(array_slice($a,$n),array_slice($a,0,$n));}
// Biblioteca de arrays bidimensionales (ejercicios 29-34).
function generaArrayBiInt($n,$m,$min,$max){$a=[];for($i=0;$i<$n&&$i<50;$i++)$a[]=generaArrayInt($m,$min,$max);return $a;}
function filaDeArrayBiInt($a,$i){return $a[$i]??[];}
function columnaDeArrayBiInt($a,$j){return array_column($a,$j);}
function coordenadasEnArrayBiInt($a,$n){foreach($a as $i=>$fila)foreach($fila as $j=>$x)if($x==$n)return [$i,$j];return [-1,-1];}
function esPuntoDeSilla($a,$i,$j){if(!isset($a[$i][$j]))return false;$x=$a[$i][$j];return $x==min($a[$i])&&$x==max(array_column($a,$j));}
function diagonal($a,$i,$j,$dir){$v=[];if(!isset($a[$i][$j]))return $v;$paso=$dir==='neso'?-1:1;while(isset($a[$i-1][$j-$paso])){$i--;$j-=$paso;}while(isset($a[$i][$j])){$v[]=$a[$i][$j];$i++;$j+=$paso;}return $v;}
// Funciones auxiliares para entrada y presentación.
function nums($s){$p=preg_split('/[\s,;]+/',trim((string)$s));return array_map('floatval',array_values(array_filter($p,fn($x)=>$x!==''&&is_numeric($x))));}
function tabla($v){echo '<table><tr>';foreach($v as $i=>$x)echo '<th>'.$i.'</th>';echo '</tr><tr>';foreach($v as $x)echo '<td>'.$x.'</td>';echo '</tr></table><br>';}
function matriz($m){echo '<table>';foreach($m as $fila){echo '<tr>';foreach($fila as $x)echo '<td>'.$x.'</td>';echo '</tr>';}echo '</table><br>';}
