": "form"}, {"s": "Condicionales", "n": 3, "statement": "Dado un número de 1 a 7, muestra el día.", "code": "echo [1=>\"lunes\",2=>\"martes\",3=>\"miércoles\",4=>\"jueves\",5=>\"viernes\",6=>\"sábado\",7=>\"domingo\"][$numero]??\"Número incorrecto\";", "fields": "<label>numero: <input name=\"numero\" type=\"number\" step=\"any\" required></label>", "mode": "form"}, {"s": "Condicionales", "n": 4, "statement": "Calcula salario semanal: primeras 40 horas a 12€, extras a 16€.", "code": "echo \"Resultado: \" . (min(40,$horas)*12+max(0,$horas-40)*16);", "fields": "<label>horas: <input name=\"horas\" type=\"number\" step=\"any\" required></label>", "mode": "form"}, {"s": "Condicionales", "n": 5, "statement": "Resuelve ax+b=0.", "code": "echo $a==0?($b==0?\"Infinitas soluciones\":\"Sin solución\"):(\"x = \".(-$b/$a));", "fields": "<label>a: <input name=\"a\" type=\"number\" step=\"any\" required></label><label>b: <input name=\"b\" type=\"number\" step=\"any\" required></label>", "mode": "form"}, {"s": "Condicionales", "n": 6, "statement": "Calcula el tiempo de caída desde altura h con g=9,81.", "code": "echo $altura<0?\"Altura inválida\":sqrt(2*$altura/9.81).\" segundos\";", "fields": "<label>altura: <input name=\"altura\" type=\"number\" step=\"any\" required></label>", "mode": "form"}, {"s": "Condicionales", "n": 7, "statement": "Calcula la media de tres notas.", "code": "echo \"Resultado: \" . (($a+$b+$c)/3);", "fields": "<label>a: <input name=\"a\" type=\"number\" step=\"any\" required></label><label>b: <input name=\"b\" type=\"number\" step=\"any\" required></label><label>c: <input name=\"c\" type=\"number\" step=\"any\" required></label>", "mode": "form"}, {"s": "Condicionales", "n": 8, "statement": "Muestra la media y su calificación.", "code": "$m=($a+$b+$c)/3;echo \"Media: $m - \".($m<5?\"Insuficiente\":($m<6?\"Suficiente\":($m<7?\"Bien\":($m<9?\"Notable\":\"Sobresaliente\"))));", "fields": "<label>a: <input name=\"a\" type=\"number\" step=\"any\" required></label><label>b: <input name=\"b\" type=\"number\" step=\"any\" required></label><label>c: <input name=\"c\" type=\"number\" step=\"any\" required></label>", "mode": "form"}, {"s": "Condicionales", "n": 9, "statement": "Resuelve ax²+bx+c=0.", "code": "if($a==0){echo $b==0?\"No es ecuación válida\":\"x = \".(-$c/$b);}else{$d=$b*$b-4*$a*$c;if($d<0)echo \"Sin soluciones reales\";else {echo \"x1 = \".((-$b+sqrt($d))/(2*$a)).\"; x2 = \".((-$b-sqrt($d))/(2*$a));}}", "fields": "<label>a: <input name=\"a\" type=\"number\" step=\"any\" required></label><label>b: <input name=\"b\" type=\"number\" step=\"any\" required></label><label>c: <input name=\"c\" type=\"number\" step=\"any\" required></label>", "mode": "form"}, {"s": "Condicionales", "n": 10, "statement": "Muestra el horóscopo según día y mes de nacimiento.", "code": "$signos=[\"Capricornio\",\"Acuario\",\"Piscis\",\"Aries\",\"Tauro\",\"Géminis\",\"Cáncer\",\"Leo\",\"Virgo\",\"Libra\",\"Escorpio\",\"Sagitario\"]; $lim=[20,19,20,20,21,21,23,23,23,23,22,22]; if(!checkdate((int)$mes,(int)$dia,2024))echo \"Fecha inválida\";else echo $dia<$lim[$mes-1]?$signos[($mes+10)%12]:$signos[$mes-1];", "fields": "<label>dia: <input name=\"dia\" type=\"number\" step=\"any\" required></label><label>mes: <input name=\"mes\" type=\"number\" step=\"any\" required></label>", "mode": "form"}, {"s": "Condicionales", "n": 11, "statement": "Calcula los segundos restantes hasta medianoche.", "code": "echo ($hora<0||$hora>23||$minuto<0||$minuto>59)?\"Hora inválida\":(24*3600-$hora*3600-$minuto*60).\" segundos\";", "fields": "<label>hora: <input name=\"hora\" type=\"number\" step=\"any\" required></label><label>minuto: <input name=\"minuto\" type=\"number\" step=\"any\" required></label>", "mode": "form"}, {"s": "Condicionales", "n": 12, "statement": "Minicuestionario de 10 preguntas de programación; cada acierto suma un punto.", "code": " $preg=[\"¿PHP se ejecuta en servidor?\"=>\"si\",\"¿HTML es un lenguaje de programación?\"=>\"no\",\"¿CSS sirve para estilos?\"=>\"si\",\"¿Una variable PHP empieza con $ ?\"=>\"si\",\"¿SQL permite consultar datos?\"=>\"si\",\"¿Un array guarda varios valores?\"=>\"si\",\"¿GET y POST son métodos HTTP?\"=>\"si\",\"¿Un bucle for puede repetirse?\"=>\"si\",\"¿JavaScript solo funciona en servidor?\"=>\"no\",\"¿=== compara también tipos en PHP?\"=>\"si\"]; $puntos=0;$i=0;foreach($preg as $pregunta=>$correcta){$respuesta=$_POST[\"q\".$i]??\"\";if($respuesta===$correcta)$puntos++;$i++;}echo \"Calificación: $puntos / 10\";", "fields": "", "mode": "quiz"}, {"s": "Condicionales", "n": 13, "statement": "Ordena tres números enteros.", "code": " $v=[$a,$b,$c];sort($v);echo implode(\", \",$v);", "fields": "<label>a: <input name=\"a\" type=\"number\" step=\"any\" required></label><label>b: <input name=\"b\" type=\"number\" step=\"any\" required></label><label>c: <input name=\"c\" type=\"number\" step=\"any\" required></label>", "mode": "form"}, {"s": "Condicionales", "n": 14, "statement": "Indica si un número es par y/o divisible por 5.", "code": "echo ($numero%2==0?\"Es par. \":\"Es impar. \").($numero%5==0?\"Divisible por 5\":\"No divisible por 5\");", "fields": "<label>numero: <input name=\"numero\" type=\"number\" step=\"any\" required></label>", "mode": "form"}, {"s": "Condicionales", "n": 15, "statement": "Cuestionario de verdadero/falso del fichero test_infidelidad.txt. Se incluye ejemplo orientativo, no determina infidelidad.", "code": " $p=0;for($i=0;$i<5;$i++)if(($_POST[\"q\".$i]??\"\")===\"si\")$p+=3;echo \"Puntuación: $p. Este cuestionario no permite determinar si alguien es infiel.\";", "fields": "", "mode": "inf"}, {"s": "Condicionales", "n": 16, "statement": "Muestra la última cifra de un entero.", "code": "echo \"Resultado: \" . (abs((int)$numero)%10);", "fields": "<label>numero: <input name=\"numero\" type=\"number\" step=\"any\" required></label>", "mode": "form"}, {"s": "Condicionales", "n": 17, "statement": "Muestra la primera cifra de un entero de hasta cinco cifras.", "code": "$v=(string)abs((int)$numero);echo strlen($v)>5?\"Máximo cinco cifras\":$v[0];", "fields": "<label>numero: <input name=\"numero\" type=\"number\" step=\"any\" required></label>", "mode": "form"}, {"s": "Condicionales", "n": 18, "statement": "Cuenta dígitos de un entero positivo o negativo de hasta cinco cifras.", "code": "$v=strlen((string)abs((int)$numero));echo $v>5?\"Máximo cinco cifras\":$v;", "fields": "<label>numero: <input name=\"numero\" type=\"number\" step=\"any\" required></label>", "mode": "form"}, {"s": "Condicionales", "n": 19, "statement": "Indica si un entero positivo de hasta cinco cifras es capicúa.", "code": "$v=(string)(int)$numero;echo ($numero<0||strlen($v)>5)?\"Número no válido\":($v===strrev($v)?\"Es capicúa\":\"No es capicúa\");", "fields": "<label>numero: <input name=\"numero\" type=\"number\" step=\"any\" required></label>", "mode": "form"}, {"s": "Bucles", "n": 1, "statement": "Muestra los múltiplos de 5 entre 0 y 100 usando for.", "code": " $i=0;for($i=0;$i<=100;$i+=5) {echo $i.\" \";}", "fields": "", "mode": "auto"}, {"s": "Bucles", "n": 2, "statement": "Muestra los múltiplos de 5 entre 0 y 100 usando while.", "code": " $i=0;while($i<=100) {echo $i.\" \"; $i+=5;}", "fields": "", "mode": "auto"}, {"s": "Bucles", "n": 3, "statement": "Muestra los múltiplos de 5 entre 0 y 100 usando do-while.", "code": " $i=0;do {echo $i.\" \"; $i+=5;}while($i<=100);", "fields": "", "mode": "auto"}, {"s": "Bucles", "n": 4, "statement": "Muestra de 320 a 160 de 20 en 20 con for.", "code": " $i=320;for($i=320;$i>=160;$i-=20) {echo $i.\" \";}", "fields": "", "mode": "auto"}, {"s": "Bucles", "n": 5, "statement": "Muestra de 320 a 160 de 20 en 20 con while.", "code": " $i=320;while($i>=160) {echo $i.\" \"; $i-=20;}", "fields": "", "mode": "auto"}, {"s": "Bucles", "n": 6, "statement": "Muestra de 320 a 160 de 20 en 20 con do-while.", "code": " $i=320;do {echo $i.\" \"; $i-=20;}while($i>=160);", "fields": "", "mode": "auto"}, {"s": "Bucles", "n": 7, "statement": "Caja fuerte con combinación de cuatro cifras y cuatro intentos.", "code": " $clave=\"1234\";$intentos=$_SESSION[\"intentos\"]??0;if($intentos>=4){echo \"Sin intentos. Reinicia la sesión.\";}elseif((string)$combinacion===$clave){echo \"La caja fuerte se ha abierto satisfactoriamente\";$_SESSION[\"intentos\"]=0;}else{$_SESSION[\"intentos\"]=$intentos+1;echo \"Lo siento, esa no es la combinación. Intentos restantes: \".(3-$intentos);}", "fields": "<label>combinacion: <input name=\"combinacion\" type=\"number\" step=\"any\" required></label>", "mode": "form"}, {"s": "Bucles", "n": 8, "statement": "Tabla de multiplicar del número introducido, con tabla HTML.", "code": "echo \"<table><tr><th>Operación</th><th>Resultado</th></tr>\";for($i=1;$i<=10;$i++)echo \"<tr><td>$numero × $i</td><td>\".($numero*$i).\"</td></tr>\";echo \"</table>\";", "fields": "<label>numero: <input name=\"numero\" type=\"number\" step=\"any\" required></label>", "mode": "form"}, {"s": "Bucles", "n": 9, "statement": "Cuenta los dígitos del número introducido.", "code": "echo strlen((string)abs((int)$numero));", "fields": "<label>numero: <input name=\"numero\" type=\"number\" step=\"any\" required></label>", "mode": "form"}, {"s": "Bucles", "n": 10, "statement": "Calcula la media de números positivos; termina con un negativo.", "code": " $v=preg_split(\"/[\\s,;]+/\",trim($numeros));$sum=0;$n=0;foreach($v as $x){if(!is_numeric($x))continue;if($x<0)break;$sum+=$x;$n++;}echo $n?\"Media: \".($sum/$n):\"Sin datos\";", "fields": "textarea", "mode": "form"}, {"s": "Bucles", "n": 11, "statement": "Muestra cinco números consecutivos, sus cuadrados y sus cubos.", "code": "echo \"<table><tr><th>Número</th><th>Cuadrado</th><th>Cubo</th></tr>\";for($i=$numero;$i<$numero+5;$i++)echo \"<tr><td>$i</td><td>\".($i*$i).\"</td><td>\".($i*$i*$i).\"</td></tr>\";echo \"</table>\";", "fields": "<label>numero: <input name=\"numero\" type=\"number\" step=\"any\" required></label>", "mode": "form"}, {"s": "Bucles", "n": 12, "statement": "Muestra los n primeros términos de Fibonacci.", "code": " $a=0;$b=1;for($i=0;$i<$n&&$i<100;$i++){echo \"$a \";[$a,$b]=[$b,$a+$b];}", "fields": "<label>n: <input name=\"n\" type=\"number\" step=\"any\" required></label>", "mode": "form"}, {"s": "Bucles", "n": 13, "statement": "Lee diez números y cuenta positivos y negativos.", "code": " $v=nums($numeros);if(count($v)!=10){echo \"Introduce 10 números\";}else{$p=0;$neg=0;foreach($v as $x){if($x>0)$p++;elseif($x<0)$neg++;}echo \"Positivos: $p; negativos: $neg\";}", "fields": "textarea", "mode": "form"}, {"s": "Bucles", "n": 14, "statement": "Calcula la potencia de una base con exponente entero positivo.", "code": " $r=1;for($i=0;$i<$exponente;$i++)$r*=$base;echo $exponente<0?\"Exponente inválido\":$r;", "fields": "<label>base: <input name=\"base\" type=\"number\" step=\"any\" required></label><label>exponente: <input name=\"exponente\" type=\"number\" step=\"any\" required></label>", "mode": "form"}, {"s": "Bucles", "n": 15, "statement": "Muestra todas las potencias desde exponente 1 hasta n sin usar funciones de exponenciación.", "code": " $r=1;for($i=1;$i<=$exponente;$i++){$r*=$base;echo \"$base ^ $i = $r<br>\";}", "fields": "<label>base: <input name=\"base\" type=\"number\" step=\"any\" required></label><label>exponente: <input name=\"exponente\" type=\"number\" step=\"any\" required></label>", "mode": "form"}, {"s": "Bucles", "n": 16, "statement": "Indica si el número es primo.", "code": "echo esPrimo((int)$numero)?\"Es primo\":\"No es primo\";", "fields": "<label>numero: <input name=\"numero\" type=\"number\" step=\"any\" required></label>", "mode": "form"}, {"s": "Bucles", "n": 17, "statement": "Suma los cien números siguientes a un entero positivo.", "code": "if($numero<=0)echo \"Debe ser positivo\";else{$s=0;for($i=1;$i<=100;$i++)$s+=$numero+$i;echo $s;}", "fields": "<label>numero: <input name=\"numero\" type=\"number\" step=\"any\" required></label>", "mode": "form"}, {"s": "Bucles", "n": 18, "statement": "Muestra los números entre dos enteros distintos de 7 en 7, desde el menor.", "code": "if($a==$b)echo \"Deben ser distintos\";else for($i=min($a,$b);$i<=max($a,$b);$i+=7)echo \"$i \";", "fields": "<label>a: <input name=\"a\" type=\"number\" step=\"any\" required></label><label>b: <input name=\"b\" type=\"number\" step=\"any\" required></label>", "mode": "form"}, {"s": "Bucles", "n": 19, "statement": "Dibuja una pirámide rellena de altura elegida con uno de cinco símbolos.", "code": " $sim=[\"●\",\"■\",\"▲\",\"◆\",\"★\"][(int)$figura]??\"●\";echo \"<pre>\";for($i=1;$i<=$altura&&$i<=35;$i++){echo str_repeat(\" \",$altura-$i);for($j=1;$j<=2*$i-1;$j++)echo $sim;echo \"\n\";}echo \"</pre>\";", "fields": "piramide", "mode": "form"}, {"s": "Bucles", "n": 20, "statement": "Dibuja una pirámide hueca de altura elegida con uno de cinco símbolos.", "code": " $sim=[\"●\",\"■\",\"▲\",\"◆\",\"★\"][(int)$figura]??\"●\";echo \"<pre>\";for($i=1;$i<=$altura&&$i<=35;$i++){echo str_repeat(\" \",$altura-$i);for($j=1;$j<=2*$i-1;$j++)echo ($i==$altura||$j==1||$j==2*$i-1?$sim:\" \");echo \"\n\";}echo \"</pre>\";", "fields": "piramide", "mode": "form"}, {"s": "Bucles", "n": 21, "statement": "Lee números hasta uno negativo: cantidad, media de impares y mayor par.", "code": " $v=nums($numeros);$n=0;$imp=[];$pares=[];foreach($v as $x){if($x<0)break;$n++;if((int)$x%2)$imp[]=$x;else $pares[]=$x;}echo \"Cantidad: $n; media impares: \".($imp?array_sum($imp)/count($imp):\"No hay\").\"; mayor par: \".($pares?max($pares):\"No hay\");", "fields": "textarea", "mode": "form"}, {"s": "Bucles", "n": 22, "statement": "Muestra todos los primos entre 2 y 100.", "code": "for($i=2;$i<=100;$i++)if(esPrimo($i))echo \"$i \";", "fields": "", "mode": "auto"}, {"s": "Bucles", "n": 23, "statement": "Suma números hasta superar 10000 y muestra total, cantidad y media.", "code": " $s=0;$n=0;foreach(nums($numeros) as $x){$s+=$x;$n++;if($s>10000)break;}echo $s>10000?\"Total $s; cantidad $n; media \".($s/$n):\"Aún no supera 10000\";", "fields": "textarea", "mode": "form"}, {"s": "Bucles", "n": 24, "statement": "Dibuja una pirámide numérica de N filas (patrón simétrico 1, 121, 12321...).", "code": "echo \"<pre>\";for($i=1;$i<=$n&&$i<=9;$i++){echo str_repeat(\" \",$n-$i);for($j=1;$j<=$i;$j++)echo $j;for($j=$i-1;$j>=1;$j--)echo $j;echo \"\n\";}echo \"</pre>\";", "fields": "<label>n: <input name=\"n\" type=\"number\" step=\"any\" required></label>", "mode": "form"}, {"s": "Bucles", "n": 25, "statement": "Muestra el número al revés.", "code": "echo strrev((string)(int)$numero);", "fields": "<label>numero: <input name=\"numero\" type=\"number\" step=\"any\" required></label>", "mode": "form"}, {"s": "Bucles", "n": 26, "statement": "Indica las posiciones (desde 1) de un dígito en el número.", "code": " $s=(string)abs((int)$numero);$pos=[];foreach(str_split($s) as $i=>$c)if($c==(string)$digito)$pos[]=$i+1;echo $pos?implode(\", \",$pos):\"No aparece\";", "fields": "<label>numero: <input name=\"numero\" type=\"number\" step=\"any\" required></label><label>digito: <input name=\"digito\" type=\"number\" step=\"any\" required></label>", "mode": "form"}, {"s": "Bucles", "n": 27, "statement": "Muestra, cuenta y suma los múltiplos de 3 hasta N.", "code": " $s=0;$c=0;for($i=3;$i<=$numero;$i+=3){echo \"$i \";$s+=$i;$c++;}echo \"<br>Cantidad: $c, suma: $s\";", "fields": "<label>numero: <input name=\"numero\" type=\"number\" step=\"any\" required></label>", "mode": "form"}, {"s": "Bucles", "n": 28, "statement": "Calcula el factorial de un entero.", "code": "if($numero<0||$numero>170)echo \"Introduce un entero entre 0 y 170\";else{$r=1;for($i=2;$i<=$numero;$i++)$r*=$i;echo $r;}", "fields": "<label>numero: <input name=\"numero\" type=\"number\" step=\"any\" required></label>", "mode": "form"}, {"s": "Bucles", "n": 29, "statement": "Muestra positivos menores que N que no sean divisibles por D.", "code": "if($divisor==0)echo \"Divisor no válido\";else for($i=1;$i<$numero;$i++)if($i%$divisor!=0)echo \"$i \";", "fields": "<label>numero: <input name=\"numero\" type=\"number\" step=\"any\" required></label><label>divisor: <input name=\"divisor\" type=\"number\" step=\"any\" required></label>", "mode": "form"}, {"s": "Arrays", "n": 1, "statement": "Genera 20 números aleatorios y muestra número, cuadrado y cubo.", "code": " $v=[];for($i=0;$i<20;$i++)$v[]=random_int(0,100);echo \"<table><tr><th>Número</th><th>Cuadrado</th><th>Cubo</th></tr>\";foreach($v as $x)echo \"<tr><td>$x</td><td>\".($x*$x).\"</td><td>\".($x*$x*$x).\"</td></tr>\";echo \"</table>\";", "fields": "", "mode": "auto"}, {"s": "Arrays", "n": 2, "statement": "Lee diez números y marca máximo y mínimo.", "code": " $v=nums($numeros);if(count($v)!=10)echo \"Introduce 10 números\";else foreach($v as $x)echo \"$x \".($x==max($v)?\"(máximo) \":\"\").($x==min($v)?\"(mínimo)\":\"\").\"<br>\";", "fields": "textarea", "mode": "form"}, {"s": "Arrays", "n": 3, "statement": "Lee quince números y rota el array una posición a la derecha.", "code": " $v=nums($numeros);if(count($v)!=15)echo \"Introduce 15 números\";else{array_unshift($v,array_pop($v));echo implode(\", \",$v);}", "fields": "textarea", "mode": "form"}, {"s": "Arrays", "n": 4, "statement": "Genera cien números de 0 a 20 y sustituye un valor por otro, resaltando los cambios.", "code": "for($i=0;$i<100;$i++){$x=random_int(0,20);echo $x==$buscar?\"<mark>$reemplazar</mark> \":\"$x \";}", "fields": "<label>buscar: <input name=\"buscar\" type=\"number\" step=\"any\" required></label><label>reemplazar: <input name=\"reemplazar\" type=\"number\" step=\"any\" required></label>", "mode": "form"}, {"s": "Arrays", "n": 5, "statement": "Lee doce temperaturas mensuales y representa barras horizontales.", "code": " $v=nums($numeros);if(count($v)!=12)echo \"Introduce 12 temperaturas\";else{foreach($v as $i=>$x){$ancho=max(0,($x+30)*4);echo \"Mes \".($i+1).\" ($x °C): <span style=\"display:inline-block;background:#79a8ed;height:12px;width:{$ancho}px\"></span><br>\";}}", "fields": "textarea", "mode": "form"}, {"s": "Arrays", "n": 6, "statement": "Lee ocho enteros y muestra pares e impares de distintos colores.", "code": " $v=nums($numeros);if(count($v)!=8)echo \"Introduce 8 números\";else foreach($v as $x)echo \"<span style=\"color:\".($x%2==0?\"blue\":\"darkorange\").\"\">$x</span> \";", "fields": "textarea", "mode": "form"}, {"s": "Arrays", "n": 7, "statement": "Genera veinte enteros y coloca primero los pares y después los impares.", "code": " $v=[];for($i=0;$i<20;$i++)$v[]=random_int(0,100);echo \"Original: \".implode(\", \",$v).\"<br>\";$p=[];$im=[];foreach($v as $x)if($x%2==0)$p[]=$x;else $im[]=$x;echo \"Ordenado: \".implode(\", \",array_merge($p,$im));", "fields": "", "mode": "auto"}, {"s": "Arrays", "n": 8, "statement": "Lee diez números y reordena los primos al principio sin perder elementos.", "code": " $v=nums($numeros);if(count($v)!=10)echo \"Introduce 10 números\";else{$p=[];$r=[];foreach($v as $x)if(esPrimo((int)$x))$p[]=$x;else $r[]=$x;tabla($v);tabla(array_merge($p,$r));}", "fields": "textarea", "mode": "form"}, {"s": "Arrays", "n": 9, "statement": "Lee diez números; mueve el de posición inicial a final y rota los demás como en el ejemplo.", "code": " $v=nums($numeros);if(count($v)!=10||$inicial<0||$final>9||$inicial>=$final)echo \"Datos incorrectos\";else{tabla($v);$x=$v[$inicial];array_splice($v,$inicial,1);array_splice($v,$final-1,0,[$x]);$v=array_merge([array_pop($v)],$v);tabla($v);}", "fields": "posiciones", "mode": "form"}, {"s": "Arrays", "n": 10, "statement": "Extrae diez cartas españolas distintas y suma sus puntos de brisca.", "code": " $puntos=[\"As\"=>11,\"Tres\"=>10,\"Rey\"=>4,\"Caballo\"=>3,\"Sota\"=>2,\"Dos\"=>0,\"Cuatro\"=>0,\"Cinco\"=>0,\"Seis\"=>0,\"Siete\"=>0];$baraja=[];foreach([\"oros\",\"copas\",\"espadas\",\"bastos\"] as $palo)foreach($puntos as $carta=>$p)$baraja[]=[\"nombre\"=>\"$carta de $palo\",\"puntos\"=>$p];shuffle($baraja);$total=0;foreach(array_slice($baraja,0,10) as $c){echo $c[\"nombre\"]