 máximo de un array.", "code": " $v=nums($numeros);$r=maximoArrayInt($v);echo is_array($r)?implode(\", \",$r):(is_bool($r)?($r?\"Verdadero\":\"Falso\"):$r);", "fields": "textarea", "mode": "form"}, {"s": "Funciones", "n": 23, "statement": "Calcula la media de un array.", "code": " $v=nums($numeros);$r=mediaArrayInt($v);echo is_array($r)?implode(\", \",$r):(is_bool($r)?($r?\"Verdadero\":\"Falso\"):$r);", "fields": "textarea", "mode": "form"}, {"s": "Funciones", "n": 24, "statement": "Comprueba si un valor existe en el array.", "code": " $v=nums($numeros);$r=estaEnArrayInt($v,(int)$numero);echo is_array($r)?implode(\", \",$r):(is_bool($r)?($r?\"Verdadero\":\"Falso\"):$r);", "fields": "textareanumero", "mode": "form"}, {"s": "Funciones", "n": 25, "statement": "Obtiene la posición de un valor en el array.", "code": " $v=nums($numeros);$r=posicionEnArray($v,(int)$numero);echo is_array($r)?implode(\", \",$r):(is_bool($r)?($r?\"Verdadero\":\"Falso\"):$r);", "fields": "textareanumero", "mode": "form"}, {"s": "Funciones", "n": 26, "statement": "Invierte el array.", "code": " $v=nums($numeros);$r=volteaArrayInt($v);echo is_array($r)?implode(\", \",$r):(is_bool($r)?($r?\"Verdadero\":\"Falso\"):$r);", "fields": "textarea", "mode": "form"}, {"s": "Funciones", "n": 27, "statement": "Rota n posiciones a la derecha.", "code": " $v=nums($numeros);$r=rotaDerechaArrayInt($v,(int)$n);echo is_array($r)?implode(\", \",$r):(is_bool($r)?($r?\"Verdadero\":\"Falso\"):$r);", "fields": "textarean", "mode": "form"}, {"s": "Funciones", "n": 28, "statement": "Rota n posiciones a la izquierda.", "code": " $v=nums($numeros);$r=rotaIzquierdaArrayInt($v,(int)$n);echo is_array($r)?implode(\", \",$r):(is_bool($r)?($r?\"Verdadero\":\"Falso\"):$r);", "fields": "textarean", "mode": "form"}, {"s": "Funciones", "n": 29, "statement": "Genera matriz n×m de enteros aleatorios.", "code": " $r=generaArrayBiInt((int)$n,(int)$m,(int)$minimo,(int)$maximo);matriz($r);", "fields": "<label>n: <input name=\"n\" type=\"number\" step=\"any\" required></label><label>m: <input name=\"m\" type=\"number\" step=\"any\" required></label><label>minimo: <input name=\"minimo\" type=\"number\" step=\"any\" required></label><label>maximo: <input name=\"maximo\" type=\"number\" step=\"any\" required></label>", "mode": "form"}, {"s": "Funciones", "n": 30, "statement": "Devuelve la fila i de la matriz.", "code": " $m=generaArrayBiInt(5,6,0,20);matriz($m); $r=filaDeArrayBiInt($m,(int)$fila);echo is_array($r)?implode(\", \",$r):(is_bool($r)?($r?\"Verdadero\":\"Falso\"):$r);", "fields": "<label>fila: <input name=\"fila\" type=\"number\" step=\"any\" required></label>", "mode": "form"}, {"s": "Funciones", "n": 31, "statement": "Devuelve la columna j de la matriz.", "code": " $m=generaArrayBiInt(5,6,0,20);matriz($m); $r=columnaDeArrayBiInt($m,(int)$columna);echo is_array($r)?implode(\", \",$r):(is_bool($r)?($r?\"Verdadero\":\"Falso\"):$r);", "fields": "<label>columna: <input name=\"columna\" type=\"number\" step=\"any\" required></label>", "mode": "form"}, {"s": "Funciones", "n": 32, "statement": "Encuentra las coordenadas de un valor o [-1,-1].", "code": " $m=generaArrayBiInt(5,6,0,20);matriz($m); $r=coordenadasEnArrayBiInt($m,(int)$numero);echo is_array($r)?implode(\", \",$r):(is_bool($r)?($r?\"Verdadero\":\"Falso\"):$r);", "fields": "<label>numero: <input name=\"numero\" type=\"number\" step=\"any\" required></label>", "mode": "form"}, {"s": "Funciones", "n": 33, "statement": "Comprueba si una posición es mínimo en su fila y máximo en su columna.", "code": " $m=generaArrayBiInt(5,6,0,20);matriz($m); $r=esPuntoDeSilla($m,(int)$fila,(int)$columna);echo is_array($r)?implode(\", \",$r):(is_bool($r)?($r?\"Verdadero\":\"Falso\"):$r);", "fields": "<label>fila: <input name=\"fila\" type=\"number\" step=\"any\" required></label><label>columna: <input name=\"columna\" type=\"number\" step=\"any\" required></label>", "mode": "form"}, {"s": "Funciones", "n": 34, "statement": "Extrae diagonal NOSE o NESO desde