// Para facilitar el estudio, el código de cada solución está disponible en la sección "Ver código".
function campo($nombre){return $_POST[$nombre]??0;}
function ejecutar($e){
 foreach($_POST as $k=>$v){if(preg_match('/^[a-zA-Z_][a-zA-Z0-9_]*$/',$k))${$k}=is_array($v)?$v:(is_numeric($v)?(float)$v:$v);}
 // Variables por defecto, para evitar avisos de PHP cuando falta algún campo.
 foreach(['a','b','c','n','numero','base','altura','radio','horas','euros','pesetas','mb','kb','dia','mes','hora','minuto','exponente','digito','divisor','buscar','reemplazar','figura','inicial','final','minimo','maximo','fila','columna','m','direccion','origen','destino','palabra','combinacion','numeros','columna'] as $nombre)if(!isset($$nombre))$$nombre=0;
 ob_start();try{eval($e['code']);}catch(Throwable $error){echo 'Error al ejecutar: '.htmlspecialchars($error->getMessage());}return ob_get_clean();
}
$salida='';if($_SERVER['REQUEST_METHOD']==='POST')$salida=ejecutar($actual);
function formulario($e){
 $fi=$e['fields'];$modo=$e['mode'];
 if($modo==='auto')return '<p>Este ejercicio no necesita datos. Pulsa Ejecutar.</p>';
 if($modo==='quiz'||$modo==='inf'){
 $preg=$modo==='quiz'?array_keys(["¿PHP se ejecuta en servidor?"=>1,"¿HTML es un lenguaje de programación?"=>1,"¿CSS sirve para estilos?"=>1,"¿Una variable PHP empieza con $ ?"=>1,"¿SQL permite consultar datos?"=>1,"¿Un array guarda varios valores?"=>1,"¿GET y POST son métodos HTTP?"=>1,"¿Un bucle for puede repetirse?"=>1,"¿JavaScript solo funciona en servidor?"=>1,"¿=== compara también tipos en PHP?"=>1]):['¿Se comunica menos contigo?','¿Ha cambiado su rutina?','¿Evita hablar de preocupaciones?','¿Pasa menos tiempo contigo?','¿Hay menos comunicación?'];
 $h='';foreach($preg as $i=>$p)$h.='<p>'.htmlspecialchars($p).' <label><input type="radio" name="q'.$i.'" value="si" required> Verdadero</label> <label><input type="radio" name="q'.$i.'" value="no"> Falso</label></p>';return $h;
 }
 if($modo==='dictionaryquiz'){
 if(!isset($_SESSION['palabras'])){$_SESSION['palabras']=array_rand($GLOBALS['diccionario'],5);}
 $h='';foreach($_SESSION['palabras'] as $i=>$es)$h.='<label>'.htmlspecialchars($es).': <input name="q'.$i.'" required></label>';return $h;
 }
 if(str_starts_with($fi,'textarea')){
 $extra=substr($fi,8);$h='<label>Números separados por espacios, comas o saltos de línea:<br><textarea name="numeros" rows="4" cols="50" required></textarea></label>';
 if($extra==='numero'||$extra==='n')$h.='<label>'.$extra.': <input type="number" name="'.$extra.'" required></label>';
 return $h;
 }
