 if($fi==='bases')return '<label>Número: <input name="numero" required></label><label>Origen: <select name="origen"><option>decimal</option><option>binario</option><option>hexadecimal</option><option>octal</option></select></label><label>Destino: <select name="destino"><option>binario</option><option>decimal</option><option>hexadecimal</option><option>octal</option></select></label>';
